<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;-XX:+ExitOnOutOfMemoryError&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   # OOM 时直接退出（让编排工具重启）</span></span>
